return await (async () => {
  const api = globalThis.dnd5eClasspack;
  if (!api?.teleport) return ui.notifications.warn("请先启用 ClassPack。");
  const targets = Array.from(game.user.targets ?? []);
  const controlled = canvas.tokens.controlled;
  const target = targets.length === 1 ? targets[0] : controlled.length === 1 ? controlled[0] : null;
  if (!target) return ui.notifications.warn("请先 target 或控制一个 Token。");
  ui.notifications.info("选择 60 英尺范围内的落点；右键或 Esc 取消。");
  return api.teleport(target, null, { range: 60, timeout: 20000, avoidOccupied: true, animate: false });
})();
